from pathlib import Path
import json
r=Path('assets-src/design-pass/kit/city/street-life')
a=json.loads((r/'remaining-layout-inputs.json').read_text());report=json.loads((r/'remaining-layout-preflight.json').read_text())
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Город — следующие предметы</title><style>*{box-sizing:border-box}body{margin:0;background:#f2eee4;color:#243c41;font:16px/1.5 system-ui}main{max-width:1250px;padding:24px;margin:auto}h1{font-size:clamp(26px,4vw,40px);line-height:1.15;margin:10px 0}h2{font-size:21px;margin:0 0 12px}.eyebrow{color:#527f81;font-size:12px;letter-spacing:.15em;text-transform:uppercase}.intro{max-width:84ch;color:#586f70}.grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:20px;margin-top:24px}.map,.details{background:#fffdf6;border:1px solid #d8d4c6;border-radius:16px;padding:16px;min-width:0}.map svg{width:100%;height:auto;display:block}.actions{display:flex;flex-wrap:wrap;gap:6px;margin:14px 0}button{border:1px solid #b5c8c4;border-radius:8px;background:#edf4ec;color:#24464a;padding:9px 12px;font:inherit;cursor:pointer;min-height:42px}button[aria-pressed=true]{background:#226b70;color:white;border-color:#226b70}button:focus-visible{outline:3px solid #d58144}.legend{font-size:13px;color:#637b78}.status{background:#fff1d7;border-left:3px solid #d09a3d;padding:10px 14px;margin:16px 0}.details p{margin:9px 0}.code{font:12px/1.5 monospace;overflow-wrap:anywhere;color:#6c8079}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}.metric{background:#edf3ec;padding:10px;border-radius:9px;font-size:13px}.metric strong{display:block;font-size:22px}.issues{padding-left:20px;font-size:14px}.foot{font-size:13px;color:#6a7b74;margin:20px 0}.focus{fill:#195f68;stroke:white;stroke-width:.3}.candidate{cursor:pointer}svg text{pointer-events:none}.selected .focus{fill:#d4853f}@media(max-width:800px){main{padding:18px}.grid{grid-template-columns:1fr}.map{padding:8px}.details{padding:18px}.actions button{padding:8px 11px}.map svg{min-height:270px}.intro{font-size:15px}}</style><main><div class="eyebrow">Электро-стол · план размещения</div><h1>Ещё восемь городских предметов</h1><p class="intro">Фрукты, велосипеды и небольшая площадка дополняют кварталы. Урны и почтовый ящик заменяют корпуса существующих игрушек, сохраняя кота, флажок, письмо и реакции на касание.</p><p class="status">Три принятые модели размещены с фактическими размерами. Остальные предметы в изготовлении; доступ и обходы проверяются отдельно.</p><div class="grid"><section class="map"><svg id="map" viewBox="-57 -40 114 80" role="img" aria-label="Карта кандидатов размещения"></svg><div class="legend">Бирюзовый — новый корпус · голубой — площадка · пунктир — запас на поворот пешехода · оранжевый — ориентиры заданий · серый — принятые предметы.</div><div class="actions" id="select"></div><button id="zoom">Приблизить выбранное место</button><button id="all">Весь город</button></section><section class="details" id="details" aria-live="polite"></section></div><p class="foot">Расчёт использует исходный код города, измеренные размеры принятых моделей и плановые размеры остальных. Квадраты существующих зданий — приближённые. Обходы, фактическая геометрия и видимость заданий ещё не приняты. Полная игра и физический iPad здесь не проверялись.</p></main><script>const input=__INPUT__; const report=__REPORT__;
const map=document.querySelector('#map');const N='http://www.w3.org/2000/svg';const el=(tag,attrs,parent=map)=>{const e=document.createElementNS(N,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));parent.append(e);return e};const rect=(a,attrs,p)=>el('rect',{x:a[0],y:a[1],width:a[2]-a[0],height:a[3]-a[1],...attrs},p);
rect([-55,-37.5,55,37.5],{fill:'#dce7c8',rx:1});const f=input.plan.field;rect([f.x0,f.z0,f.x1,f.z1],{fill:'#b4cf91'});
for(const l of input.plan.lanes){const points=l.pts.map(p=>p.join(',')).join(' ');el('polyline',{points,fill:'none',stroke:'#e8d5b2','stroke-width':l.w+3.6});el('polyline',{points,fill:'none',stroke:'#909b9b','stroke-width':l.w});}
rect([35.4,-37.5,38.6,17],{fill:'#75bdcf'});el('ellipse',{cx:37,cy:19.5,rx:5,ry:3.2,fill:'#75bdcf'});
for(const g of input.buildings)for(const[x,z,yaw,s]of g.items){const w=g.fit.width*s;rect([x-w/2,z-w/2,x+w/2,z+w/2],{fill:'#c3a986',stroke:'#9e8869','stroke-width':.15})}
for(const k of input.keep)el('circle',{cx:k.x,cy:k.z,r:1.6,fill:'#df976e',opacity:.35});
for(const l of input.paths)el('polyline',{points:l.points.map(p=>p.join(',')).join(' '),fill:'none',stroke:'#b9625c','stroke-width':.3,'stroke-dasharray':'1 .5'});
for(const p of input.first3){const[x,z]=p.position,[w,h,d]=p.xyz;rect([x-w/2,z-d/2,x+w/2,z+d/2],{fill:'#788b87'})}
const labels={'named-anchor-clearance':'Недостаточный запас до ориентира задания.','protected-line-clearance':'Требуется отступ от защищённого маршрута.','road-overlap':'Корпус пересекает дорогу.','water-overlap':'Корпус пересекает воду.','pedestrian-envelope-crosses-unfiltered-pavement-line':'Нужно исключить корпус с запасом из маршрута пешехода.','existing-decor-estimate-overlap':'Проверить отмеченный существующий декор по фактической геометрии.'};let selected=0;
function choose(i){selected=i;document.querySelectorAll('#select button').forEach((e,j)=>e.setAttribute('aria-pressed',j===i));document.querySelectorAll('.candidate').forEach((e,j)=>e.classList.toggle('selected',j===i));const p=input.layout.items[i],r=report.items[i];const det=document.querySelector('#details');det.replaceChildren();const text=(tag,t,cls)=>{const e=document.createElement(tag);e.textContent=t;if(cls)e.className=cls;det.append(e);return e};text('h2',`${i+1}. ${p.label}`);text('p',p.id,'code');text('p',`Центр (${p.position.join('; ')}), размер ${(p.actualXYZ??p.targetXYZ).map(x=>x.toFixed(3)).join(' × ')}.`);text('p',p.mode==='existing-interactive-shell'?'Существующая интерактивная игрушка. Меняется только корпус.':p.actualXYZ?'Принятая модель, размещённая по фактическим размерам.':'Новое предварительное место.');const m=text('div','','metrics');for(const [v,t]of[[r.nearestPoint.margin,'запас до ориентира'],[r.roadGap,'от корпуса до дороги']]){const e=document.createElement('div');e.className='metric';const s=document.createElement('strong');s.textContent=v;e.append(s,document.createTextNode(t));m.append(e)}text('p',r.issues.length?'Что уточнить перед интеграцией:':'По предварительному расчёту корпус не пересекает дороги и защищённые зоны.');const ul=text('ul','','issues');for(const issue of r.issues){const li=document.createElement('li');li.textContent=labels[issue];ul.append(li)}if(r.nearbyDecor.length)text('p','Рядом: '+r.nearbyDecor.map(q=>`${q.model} (${q.position.join('; ')})`).join(', '),'code');if(p.id==='city-postbox')text('p','Нынешнее место рядом с корзиной бабушки не проходит консервативный запас −0,25. Нужен осмотр либо перенос всего ящика.');if(p.id==='city-bike-rack')text('p','С площадки убраны два куста и один цветочный пучок; прочий декор сохранён.');text('p',p.note,'code')}
input.layout.items.forEach((p,i)=>{const r=report.items[i],g=el('g',{class:'candidate'});if(p.pad)rect(p.pad,{fill:'#c5e3ef',opacity:.8},g);rect(r.pedestrianEnvelope,{fill:'none',stroke:'#447f84','stroke-width':.18,'stroke-dasharray':'.6 .4'},g);rect(r.rotatedAabb,{fill:'#226b70'},g);const[x,z]=p.position;el('circle',{cx:x,cy:z-2.5,r:1.45,class:'focus'},g);const t=el('text',{x,y:z-1.95,'text-anchor':'middle','font-size':1.65,fill:'white'},g);t.textContent=i+1;g.addEventListener('click',()=>choose(i));const b=document.createElement('button');b.textContent=i+1;b.setAttribute('aria-label',p.label);b.onclick=()=>choose(i);document.querySelector('#select').append(b)});
document.querySelector('#zoom').onclick=()=>{const[x,z]=input.layout.items[selected].position;map.setAttribute('viewBox',`${x-12} ${z-9} 24 18`)};document.querySelector('#all').onclick=()=>map.setAttribute('viewBox','-57 -40 114 80');choose(0);
</script></html>'''
page=page.replace('__INPUT__',json.dumps(a,ensure_ascii=False)).replace('__REPORT__',json.dumps(report,ensure_ascii=False));(r/'remaining-layout.html').write_text(page);print('Built remaining-layout.html')
